<template>
  <div class="xlab-root plaza-page" :class="{ 'detail-open': selectedId }">
    <div class="xlab-navdock" :class="{ 'nav-open': navOpen }" @mouseenter="navEnter" @mouseleave="navLeave"><MenuComponent /></div>
    <aside class="planet-rail" aria-label="XLAB 品牌导航">
      <router-link to="/lab" class="planet-back" aria-label="返回 XLAB 首页"><el-icon><ArrowLeft /></el-icon></router-link>
      <div class="planet-mark" aria-hidden="true"><span>X</span><small>LAB</small></div>
      <span class="planet-coordinate">22.3193 N<br>114.1694 E</span>
    </aside>
    <main class="plaza-shell">
      <header class="plaza-header">
        <div><p class="plaza-kicker">XLAB / PROJECT DIRECTORY / 2026</p><h1>PROJECT PLAZA<span>_</span></h1><p class="plaza-intro">浏览训练营成果与成员自由分享的项目，找到值得继续理解、协作和记录的工作。</p></div>
        <button type="button" class="publish-button" @click="router.push('/lab/projects/new')"><el-icon><Plus /></el-icon><span>发布项目</span></button>
      </header>
      <section class="discovery-panel" aria-label="项目搜索与筛选">
        <label class="project-search"><el-icon><Search /></el-icon><input v-model="keyword" type="search" placeholder="搜索项目名称、简介或关键词" @keyup.enter="load" /><button type="button" @click="load">SEARCH</button></label>
        <div class="filter-line"><span class="filter-label">来源</span><div class="filter-options"><button v-for="filter in sourceFilters" :key="String(filter.value)" type="button" :class="{ active: filters.source === filter.value }" @click="setFilter('source', filter.value)">{{ filter.label }}</button></div></div>
        <div class="filter-line"><span class="filter-label">状态</span><div class="filter-options"><button v-for="filter in statusFilters" :key="String(filter.value)" type="button" :class="{ active: filters.project_status === filter.value }" @click="setFilter('project_status', filter.value)">{{ filter.label }}</button></div></div>
        <div v-if="allTags.length" class="filter-line tag-line"><span class="filter-label">标签</span><div class="filter-options tag-options"><button type="button" :class="{ active: !filters.tag }" @click="setFilter('tag', null)">全部</button><button v-for="tag in allTags" :key="tag" type="button" :class="{ active: filters.tag === tag }" @click="setFilter('tag', tag)">{{ tag }}</button></div></div>
      </section>
      <section class="catalog-results" aria-label="项目列表">
        <div class="catalog-toolbar"><div><strong>{{ projects.length }}</strong><span> PROJECTS FOUND</span></div><div class="toolbar-actions"><button v-if="hasFilters" type="button" @click="clearFilters">清除筛选</button><label>排序<select v-model="sortMode"><option value="updated">最近更新</option><option value="popular">最多浏览</option><option value="favorites">最多收藏</option></select></label></div></div>
        <div v-if="loading" class="grid-loading"><div v-for="index in 6" :key="index" class="project-skeleton"></div></div>
        <div v-else-if="!projects.length" class="xl-empty"><el-icon><Grid /></el-icon><strong>NO PROJECT SIGNAL</strong><p>没有匹配的项目，调整筛选条件或发布第一个项目。</p><button type="button" @click="clearFilters">查看全部项目</button></div>
        <div v-else class="project-grid">
          <button v-for="project in sortedProjects" :key="project.id" type="button" class="p-card" :class="{ selected: String(project.id) === selectedId }" @click="openDetail(project.id)">
            <div :class="['p-cover', `cover-${project.source}`]">
              <DewImage v-if="project.cover_thumb || project.cover" class="cover-img" :src="assetUrl(project.cover_thumb || project.cover)" alt="" />
              <div v-else class="cover-fallback" aria-hidden="true"><span></span><b class="cover-char">{{ project.title.charAt(0) }}</b></div>
              <span :class="['src-badge', `src-${project.source}`]">{{ project.source_text }}</span><span v-if="project.status === 'hidden'" class="hidden-badge">已下架</span>
            </div>
            <div class="p-body"><div class="p-card-topline"><span :class="['p-status', `ps-${project.project_status}`]"><i></i>{{ project.project_status_text }}</span><span>{{ project.track_text || '其他' }}</span></div><h2>{{ project.title }}</h2><p>{{ project.summary || project.description || '这个项目正在补充介绍。' }}</p><div class="p-tags"><span v-for="tag in (project.tags || []).slice(0, 3)" :key="tag">{{ tag }}</span></div><div class="p-bottom"><div class="creator"><span>{{ (project.owner_name || 'X').charAt(0) }}</span><b>{{ project.owner_name || 'XLAB MEMBER' }}</b></div><div class="engagement"><span><el-icon><View /></el-icon>{{ project.view_count ?? 0 }}</span><span><el-icon><Star /></el-icon>{{ project.favorite_count ?? 0 }}</span></div></div></div>
          </button>
        </div>
      </section>
    </main>
    <ProjectDetailDrawer v-if="selectedId" :project-id="selectedId" @close="closeDetail" @updated="syncProject" />
  </div>
</template>

<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { ElMessage } from 'element-plus';
import { ArrowLeft, Grid, Plus, Search, Star, View } from '@element-plus/icons-vue';
import DewImage from '@bme/dew-ui/DewImage.vue';
import MenuComponent from '../components/MenuComponent.vue';
import ProjectDetailDrawer from '../components/ProjectDetailDrawer.vue';
import { assetUrl } from '../services/campService';
import { showcaseService } from '../services/showcaseService';
import '../styles/xlab.css';
const router = useRouter(); const route = useRoute();
const navOpen = ref(false); const loading = ref(true); const projects = ref([]); const allTags = ref([]); const keyword = ref(''); const sortMode = ref('updated');
const filters = ref({ source: null, project_status: null, tag: null });
let navCloseTimer = null; let loadVersion = 0;
const sourceFilters = [{ label: '全部', value: null }, { label: '营期项目', value: 'camp' }, { label: '自由分享', value: 'community' }];
const statusFilters = [{ label: '全部', value: null }, { label: '构思中', value: 'idea' }, { label: '进行中', value: 'ongoing' }, { label: '已完成', value: 'done' }];
const hasFilters = computed(() => Boolean(filters.value.source || filters.value.project_status || filters.value.tag || keyword.value.trim()));
const selectedId = computed(() => /^\d+$/.test(String(route.query.project || '')) ? String(route.query.project) : null);
const sortedProjects = computed(() => [...projects.value].sort((a, b) => {
  if (sortMode.value === 'popular') return (b.view_count || 0) - (a.view_count || 0);
  if (sortMode.value === 'favorites') return (b.favorite_count || 0) - (a.favorite_count || 0);
  return new Date(b.updated_at || b.created_at || 0) - new Date(a.updated_at || a.created_at || 0);
}));
function navEnter() { clearTimeout(navCloseTimer); navOpen.value = true; }
function navLeave() { clearTimeout(navCloseTimer); navCloseTimer = setTimeout(() => { navOpen.value = Boolean(document.querySelector('.dew-popover')); }, 240); }
function setFilter(key, value) { filters.value = { ...filters.value, [key]: value }; load(); }
function clearFilters() { filters.value = { source: null, project_status: null, tag: null }; keyword.value = ''; load(); }
function openDetail(id) { router.replace({ query: { ...route.query, project: String(id) } }); }
function closeDetail() { const query = { ...route.query }; delete query.project; router.replace({ query }); }
function syncProject(updated) { projects.value = projects.value.map((project) => project.id === updated.id ? { ...project, ...updated } : project); }
async function load() {
  const version = ++loadVersion; loading.value = true;
  try { const params = {}; if (filters.value.source) params.source = filters.value.source; if (filters.value.project_status) params.project_status = filters.value.project_status; if (filters.value.tag) params.tag = filters.value.tag; if (keyword.value.trim()) params.q = keyword.value.trim(); const data = await showcaseService.fetchProjects(params); if (version !== loadVersion) return; projects.value = data.projects || []; allTags.value = data.all_tags || []; }
  catch (error) { if (version === loadVersion) ElMessage.error(error.response?.data?.message || '加载项目列表失败'); }
  finally { if (version === loadVersion) loading.value = false; }
}
 onMounted(load); onBeforeUnmount(() => clearTimeout(navCloseTimer));
</script>

