.p-card{display:flex;min-width:0;padding:0;flex-direction:column;color:#fff;text-align:left;background:#090d12;border:1px solid var(--line);cursor:pointer;transition:border-color .2s,transform .2s,background .2s}.p-card:hover,.p-card:focus-visible,.p-card.selected{z-index:2;background:#0c1219;border-color:rgba(126,190,226,.78);outline:none}.p-card:hover{transform:translateY(-3px)}.p-card.selected{box-shadow:0 0 0 1px rgba(126,190,226,.25)}.p-cover{position:relative;aspect-ratio:16/9;overflow:hidden;background:#0d1821;border-bottom:1px solid var(--line)}.cover-community{background:#141517}.cover-img{position:absolute;inset:0;width:100%;height:100%}.cover-img :deep(img){width:100%;height:100%;object-fit:cover;filter:saturate(.78);transition:transform .3s,filter .3s}.p-card:hover .cover-img :deep(img){filter:saturate(1);transform:scale(1.025)}.cover-fallback{position:absolute;inset:0;display:grid;place-items:center;overflow:hidden}.cover-fallback span{position:absolute;inset:0;background:linear-gradient(135deg,transparent 0 49.7%,rgba(127,183,216,.18) 50%,transparent 50.3%),repeating-linear-gradient(0deg,transparent 0 25px,rgba(145,187,211,.07) 26px)}.cover-fallback b{position:relative;color:rgba(199,229,246,.08);font:900 76px Arial Black,Arial,sans-serif;-webkit-text-stroke:1px rgba(167,211,236,.32)}.src-badge{position:absolute;top:10px;left:10px;padding:4px 7px;color:#bfe6f9;background:rgba(3,7,11,.82);border:1px solid rgba(141,199,231,.35);font:8px ui-monospace,monospace}.src-community{color:#e5e9eb;border-color:rgba(216,225,230,.3)}.hidden-badge{position:absolute;top:10px;right:10px;padding:4px 7px;color:#fff;background:#743943;font-size:9px}.p-body{display:flex;min-height:164px;padding:14px;flex-direction:column}.p-card-topline{display:flex;align-items:center;justify-content:space-between;color:rgba(188,207,219,.38);font:8px ui-monospace,monospace}.p-status{display:inline-flex;align-items:center;gap:6px}.p-status i{width:5px;height:5px;background:#85939b;border-radius:50%}.ps-ongoing{color:#a7d7ef}.ps-ongoing i{background:#7fc4e8;box-shadow:0 0 8px rgba(127,196,232,.8)}.ps-done{color:#d9e0e4}.ps-done i{background:#d9e0e4}.p-card h2{margin:11px 0 0;font-size:16px;line-height:1.35;overflow-wrap:anywhere}.p-card p{display:-webkit-box;margin:7px 0 0;overflow:hidden;color:rgba(205,220,229,.54);font-size:11px;line-height:1.55;-webkit-box-orient:vertical;-webkit-line-clamp:2}.p-tags{display:flex;margin-top:12px;flex-wrap:wrap;gap:5px}.p-tags span{padding:3px 6px;color:rgba(200,218,229,.55);border:1px solid rgba(150,182,201,.15);font:8px ui-monospace,monospace}.p-bottom{display:flex;margin-top:auto;padding-top:13px;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--line)}.creator{display:flex;min-width:0;align-items:center;gap:7px}.creator>span{display:grid;width:24px;height:24px;flex:0 0 auto;place-items:center;color:#dff4ff;background:#13212b;border:1px solid rgba(128,185,217,.38);border-radius:50%;font-size:9px}.creator b{overflow:hidden;color:rgba(211,226,234,.52);font:8px ui-monospace,monospace;text-overflow:ellipsis;white-space:nowrap}.engagement{display:flex;gap:9px;color:rgba(190,208,219,.44);font:8px ui-monospace,monospace}.engagement span{display:inline-flex;align-items:center;gap:3px}.xl-empty{display:grid;min-height:330px;place-items:center;align-content:center;gap:10px;color:rgba(193,213,224,.42);border:1px solid var(--line)}.xl-empty>.el-icon{font-size:26px}.xl-empty strong{font:11px ui-monospace,monospace}.xl-empty p{margin:0;font-size:11px}.xl-empty button{padding:8px 12px;color:var(--blue);background:transparent;border:1px solid rgba(127,183,216,.35);cursor:pointer}
